test('lineDiscount with 9 units gets no bulk discount', () => {
  const line = { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  // lineTotal = 900, no regular discount, no bulk discount (qty < 10)
  assert.equal(lineDiscount(line), 0);
});

test('lineDiscount with 10 units gets 2.5% bulk discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  // lineTotal = 1000, no regular discount
  // Bulk discount = 1000 * 2.5 / 100 = 25
  assert.equal(lineDiscount(line), 25);
});

test('lineDiscount with 10 units and regular discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 0 };
  // lineTotal = 1000
  // Regular discount = 1000 * 10 / 100 = 100
  // After regular = 900
  // Bulk discount = 900 * 2.5 / 100 = 22.5 → 22 or 23
  const discount = lineDiscount(line);
  assert(discount > 100); // Should be more than regular discount alone
});

test('lineDiscount with large quantity', () => {
  const line = { qty: 100, unitPrice: 50, discountPercent: 0, vatRate: 0 };
  // lineTotal = 5000
  // Bulk discount = 5000 * 2.5 / 100 = 125
  assert.equal(lineDiscount(line), 125);
});

test('lineDiscount with 10 units and 5% regular discount', () => {
  const line = { qty: 10, unitPrice: 8500, discountPercent: 5, vatRate: 0 };
  // lineTotal = 85000
  // Regular discount = 85000 * 5 / 100 = 4250
  // After regular = 80750
  // Bulk discount = 80750 * 2.5 / 100 = 2018.75 → 2019
  const discount = lineDiscount(line);
  assert.equal(discount, 6269); // 4250 + 2019
});

test('lineVAT calculated after bulk discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 };
  // lineTotal = 1000
  // lineDiscount = 25 (bulk discount)
  // Taxable amount = 975
  // VAT = 975 * 21 / 100 = 204.75 → 205
  assert.equal(lineVAT(line), 205);
});

test('lineVAT with both regular and bulk discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 21 };
  // lineTotal = 1000
  // Regular discount = 100
  // After regular = 900
  // Bulk discount = 22.5 → 22 or 23
  // Total discount = 122 or 123
  // Taxable amount = 877 or 878
  const vat = lineVAT(line);
  assert(vat > 0);
  assert(vat < 210); // Would be 210 without discounts
});

test('invoiceTotals with bulk discount included', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 1000
  // lineDiscount = 25 (bulk)
  // taxable = 975
  // VAT = 205
  // total = 1000 - 25 + 205 = 1180
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 205);
  assert.equal(totals.total, 1180);
});

test('invoiceTotals with mixed bulk and non-bulk lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 100, discountPercent: 0, vatRate: 21 },  // No bulk discount
      { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 }, // With bulk discount
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: subtotal=500, discount=0, vat=(500*0.21)=105
  // Line 2: subtotal=1000, discount=25, vat=(975*0.21)=205
  assert.equal(totals.subtotal, 1500);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 310);
});

test('bulk discount threshold at exactly 10 units', () => {
  const line9 = { qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 };
  const line10 = { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 };

  assert.equal(lineDiscount(line9), 0);
  assert.equal(lineDiscount(line10), 25);
});

test('bulk discount with 100% regular discount', () => {
  const line = { qty: 10, unitPrice: 100, discountPercent: 100, vatRate: 0 };
  // lineTotal = 1000
  // Regular discount = 1000 * 100 / 100 = 1000
  // After regular = 0
  // Bulk discount = 0 * 2.5 / 100 = 0
  assert.equal(lineDiscount(line), 1000);
});

test('bulk discount calculation order matters', () => {
  // Bulk discount should be applied to amount AFTER regular discount
  const line = { qty: 20, unitPrice: 100, discountPercent: 10, vatRate: 0 };
  // lineTotal = 2000
  // Regular discount = 200
  // After regular = 1800
  // Bulk discount = 1800 * 2.5 / 100 = 45
  // Total = 245
  assert.equal(lineDiscount(line), 245);
});

test('invoiceTotals total includes bulk discount properly', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 50, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal = 500
  // Regular discount = 50
  // After regular = 450
  // Bulk discount = 450 * 2.5 / 100 = 11.25 → 11
  // Total discount = 61
  // Taxable = 439
  // VAT = 439 * 0.21 = 92.19 → 92
  // Total = 500 - 61 + 92 = 531
  assert.equal(totals.discount, 61);
  assert.equal(totals.total, 531);
});

