3	/** Exchange rates: units of that currency per euro. */
4	export const RATES = {
5	  EUR: 1,
6	  USD: 1.085,
7	  GBP: 0.8425,
8	};
9	
10	/**
11	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
12	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
13	 * @param {number} x
14	 * @returns {number}
15	 */
16	export function roundCents(x) {
17	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
18	  const floor = Math.floor(r);
19	  const diff = r - floor;
20	  if (diff > 0.5) return floor + 1;
21	  if (diff < 0.5) return floor === 0 ? 0 : floor;
22	  return floor % 2 === 0 ? floor : floor + 1;
23	}
24	
25	/**
26	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
27	 * @param {number} cents
28	 * @returns {string}
29	 */
30	export function formatEuros(cents) {
31	  const sign = cents < 0 ? '-' : '';
32	  const abs = Math.abs(cents);
33	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
34	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
35	}
36	
37	/**
38	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
39	 * @param {string} text
40	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
41	 */
42	export function parseEuros(text) {
43	  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
44	  if (!m) return fail('AMOUNT_INVALID');
45	  const euros = Number(m[1].replace(/,/g, ''));
46	  const cents = Number((m[2] ?? '').padEnd(2, '0'));
47	  return ok(euros * 100 + cents);
48	}
49	
50	/**
51	 * Convert an amount in EUR cents to another currency's cents.
52	 * @param {number} cents - Amount in EUR cents
53	 * @param {string} currency - Target currency code (EUR, USD, GBP)
54	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
55	 */
56	export function convert(cents, currency) {
57	  if (!(currency in RATES)) {
58	    return fail('UNKNOWN_CURRENCY');
59	  }
60	  const rate = RATES[currency];
61	  const converted = roundCents(cents * rate);
62	  return ok(converted);
63	}
64	
65	/**
66	 * Format cents in a given currency for display.
67	 * @param {number} cents - Amount in cents of the given currency
68	 * @param {string} currency - Currency code (EUR, USD, GBP)
69	 * @returns {string} - Formatted amount (e.g., "$1,234.56", "£1,234.56", "€1,234.56")
70	 */
71	export function formatMoney(cents, currency) {
72	  const sign = cents < 0 ? '-' : '';
73	  const abs = Math.abs(cents);
74	  const symbol = currency === 'USD' ? '$' : currency === 'GBP' ? '£' : '€';
75	  const units = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
76	  return `${sign}${symbol}${units}.${String(abs % 100).padStart(2, '0')}`;
77	}
