1	import { roundCents } from './money.js';
2	
3	/**
4	 * Calculate the total for a single line (qty × unitPrice in cents).
5	 * @param {{ qty: number, unitPrice: number }} line
6	 * @returns {number}
7	 */
8	export function lineTotal(line) {
9	  return roundCents(line.qty * line.unitPrice);
10	}
11	
12	/**
13	 * Calculate the discount amount for a single line.
14	 * Includes regular discount (tier or line-specific) and bulk discount (2.5% off for 10+ units).
15	 * Bulk discount is applied after regular discount to the remaining amount.
16	 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
17	 * @returns {number}
18	 */
19	export function lineDiscount(line) {
20	  const discountPercent = line.discountPercent ?? 0;
21	  const total = lineTotal(line);
22	
23	  // Calculate regular discount
24	  const regularDiscount = roundCents(total * discountPercent / 100);
25	
26	  // Calculate bulk discount (2.5% off for 10+ units, applied after regular discount)
27	  let bulkDiscount = 0;
28	  if (line.qty >= 10) {
29	    const amountAfterRegular = total - regularDiscount;
30	    bulkDiscount = roundCents(amountAfterRegular * 2.5 / 100);
31	  }
32	
33	  return Math.max(0, regularDiscount + bulkDiscount);
34	}
35	
36	/**
37	 * Calculate the VAT amount for a single line (on the amount after discount).
38	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
39	 * @returns {number}
40	 */
41	export function lineVAT(line) {
42	  const total = lineTotal(line);
43	  const discount = lineDiscount(line);
44	  const taxableAmount = total - discount;
45	  const vatRate = line.vatRate ?? 0;
46	  const vat = roundCents(taxableAmount * vatRate / 100);
47	  return Math.max(0, vat);
48	}
49	
50	/**
51	 * Calculate subtotal, discount, VAT, voucher, and total for an invoice.
52	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }>, voucher?: { code: string, amount: number } }} invoice
53	 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
54	 */
55	export function invoiceTotals(invoice) {
56	  let subtotal = 0;
57	  let discount = 0;
58	  let vat = 0;
59	  for (const line of invoice.lines) {
60	    subtotal += lineTotal(line);
61	    discount += lineDiscount(line);
62	    vat += lineVAT(line);
63	  }
64	  subtotal = roundCents(subtotal);
65	  discount = roundCents(discount);
66	  vat = roundCents(vat);
67	  const voucher = invoice.voucher?.amount ?? 0;
68	  const total = Math.max(0, roundCents(subtotal - discount + vat - voucher));
69	  return {
70	    subtotal,
71	    discount,
72	    vat,
73	    voucher,
74	    total,
75	  };
76	}
