23	  if (!customerResult.ok) return customerResult;
24	
25	  // Validate issueDate
26	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
27	
28	  // Calculate due date based on terms
29	  const dueDateResult = calculateDueDate(issueDate, terms);
30	  if (!dueDateResult.ok) return dueDateResult;
31	  const dueDate = dueDateResult.value;
32	
33	  // Validate lines
34	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
35	
36	  // Get tier discount for lines without their own discount
37	  const customer = customerResult.value;
38	  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
39	
40	  // Validate and enrich each line
41	  const enrichedLines = [];
42	  for (const line of lines) {
43	    // Validate qty
44	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
45	
46	    // Validate discountPercent (if provided, must be valid)
47	    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
48	      return fail('DISCOUNT_INVALID');
49	    }
50	    // Use line's discount if provided, otherwise use tier discount
51	    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
52	
53	    // Validate SKU
54	    const productResult = getProduct(line.sku);
55	    if (!productResult.ok) return productResult;
56	
57	    const product = productResult.value;
58	    enrichedLines.push({
59	      sku: line.sku,
60	      name: product.name,
61	      qty: line.qty,
62	      unitPrice: product.unitPrice,
63	      vatRate: product.vatRate,
64	      discountPercent,
65	    });
66	  }
67	
68	  return ok({
69	    customerId: normalizedCustomerId,
70	    issueDate,
71	    status: 'draft',
72	    terms,
73	    dueDate,
