120	        unitPrice: product.unitPrice,
121	        vatRate: product.vatRate,
122	        discountPercent: discount,
123	      },
124	    ];
125	  }
126	
127	  return ok({
128	    ...invoice,
129	    lines: newLines,
130	  });
