50	/**
51	 * Merge two customers: move all invoices from one to another and delete the first.
52	 * @param {Array} customers - Array of customer objects
53	 * @param {Array} invoices - Array of invoice objects
54	 * @param {string} fromId - Customer to merge from (will be deleted)
55	 * @param {string} intoId - Customer to merge into (will receive invoices)
56	 * @returns {{ ok: true, value: { customers: Array, invoices: Array } } | { ok: false, error: string }}
57	 */
58	export function mergeCustomers(customers, invoices, fromId, intoId) {
59	  const normalizedFromId = normalizeId(fromId);
60	  const normalizedIntoId = normalizeId(intoId);
61	
62	  // Check for same customer error first
63	  if (normalizedFromId === normalizedIntoId) {
64	    return fail('SAME_CUSTOMER');
65	  }
66	
67	  // Check both customers exist
68	  const fromExists = customers.some((c) => c.id === normalizedFromId);
69	  if (!fromExists) {
70	    return fail('CUSTOMER_NOT_FOUND');
71	  }
72	
73	  const intoExists = customers.some((c) => c.id === normalizedIntoId);
74	  if (!intoExists) {
75	    return fail('CUSTOMER_NOT_FOUND');
76	  }
77	
78	  // Create new customers array without the fromId customer
79	  const newCustomers = customers.filter((c) => c.id !== normalizedFromId);
80	
81	  // Create new invoices array with customerId updated for affected invoices
82	  const newInvoices = invoices.map((inv) => {
83	    if (inv.customerId === normalizedFromId) {
84	      return { ...inv, customerId: normalizedIntoId };
85	    }
86	    return inv;
87	  });
88	
89	  return ok({
90	    customers: newCustomers,
91	    invoices: newInvoices,
92	  });
93	}
